// Gestos apenas pelas alças: o restante da tela continua livre para rolagem.
export function bindDrag(root,{onDrop,onMove,onAnnounce=()=>{}}){
  root._dragCleanup?.();let candidate=null,active=null,timer,frame,ghost,highlight,suppressUntil=0;
  const clearHighlight=()=>{highlight?.classList.remove('drop-before','drop-after','drop-zone-active');highlight=null};
  function cleanup(){clearTimeout(timer);cancelAnimationFrame(frame);clearHighlight();active?.source.classList.remove('is-dragging');ghost?.remove();ghost=null;candidate=null;active=null;document.documentElement.classList.remove('drag-active')}
  function destination(x,y){const el=document.elementFromPoint(x,y);if(!el)return null;
    if(active.type==='area'){const target=el.closest('[data-drag-area]');if(!target||target.dataset.dragArea===active.id)return null;const rect=target.getBoundingClientRect();const pos=y>rect.top+rect.height*.8?'after':y<rect.top+rect.height*.2?'before':x>rect.left+rect.width/2?'after':'before';return {node:target,type:'area',id:target.dataset.dragArea,position:pos}}
    const tab=el.closest('[data-drag-area]');if(tab)return {node:tab,type:'area',id:tab.dataset.dragArea,position:'inside'};
    const target=el.closest('[data-drag-item]');if(target&&target.dataset.dragItem!==active.id){const r=target.getBoundingClientRect();return {node:target,type:'item',id:target.dataset.dragItem,position:y>r.top+r.height/2?'after':'before'}}
    const zone=el.closest('[data-drop-priority],[data-drop-area]');if(zone)return {node:zone,type:zone.dataset.dropPriority?'priority':'area',id:zone.dataset.dropPriority||zone.dataset.dropArea,position:'inside'};return null;
  }
  function track(){if(!active)return;const margin=75,dy=active.y<margin?-10:active.y>innerHeight-margin?10:0;if(dy)window.scrollBy(0,dy);frame=requestAnimationFrame(track)}
  function begin(){if(!candidate)return;active=candidate;candidate=null;active.source.classList.add('is-dragging');document.documentElement.classList.add('drag-active');ghost=document.createElement('div');ghost.className='drag-ghost';ghost.textContent=active.label;document.body.append(ghost);ghost.style.left=active.x+'px';ghost.style.top=active.y+'px';onAnnounce('Movendo '+active.label);try{active.handle.setPointerCapture(active.pointerId)}catch{}track()}
  function down(e){if(e.button!==0)return;const handle=e.target.closest('[data-drag-handle]');if(!handle||!root.contains(handle))return;const source=handle.closest('[data-drag-item],[data-drag-area]');if(!source)return;cleanup();candidate={handle,source,pointerId:e.pointerId,pointerType:e.pointerType,type:source.dataset.dragArea?'area':'item',id:source.dataset.dragArea||source.dataset.dragItem,label:source.dataset.dragLabel||handle.getAttribute('aria-label')||'Item',x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY};if(e.pointerType!=='mouse')timer=setTimeout(begin,300)}
  function move(e){if(candidate){const distance=Math.hypot(e.clientX-candidate.startX,e.clientY-candidate.startY);if(candidate.pointerType==='mouse'&&distance>4)begin();else if(distance>12){cleanup();return}}if(!active||active.pointerId!==e.pointerId)return;e.preventDefault();active.x=e.clientX;active.y=e.clientY;ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';clearHighlight();active.target=destination(e.clientX,e.clientY);if(active.target){highlight=active.target.node;highlight.classList.add(active.target.position==='inside'?'drop-zone-active':'drop-'+active.target.position)}}
  function up(e){if(!active){cleanup();return}if(active.pointerId!==e.pointerId)return;const data={type:active.type,id:active.id,target:active.target};suppressUntil=Date.now()+500;cleanup();if(data.target)onDrop(data);else onAnnounce('Movimento cancelado.')}
  function click(e){if(Date.now()<suppressUntil){e.preventDefault();e.stopImmediatePropagation()}}
  function key(e){const handle=e.target.closest('[data-drag-handle]')||(e.altKey?e.target.closest('[data-drag-area]'):null);if(!handle)return;if((e.altKey||handle.matches('button'))&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const source=handle.closest('[data-drag-item],[data-drag-area]');onMove({type:source.dataset.dragArea?'area':'item',id:source.dataset.dragArea||source.dataset.dragItem,delta:['ArrowUp','ArrowLeft'].includes(e.key)?-1:1})}else if(e.key==='Escape')cleanup()}
  const context=e=>{if(e.target.closest('[data-drag-handle]'))e.preventDefault()};
  root.addEventListener('contextmenu',context);root.addEventListener('pointerdown',down);root.addEventListener('pointermove',move);root.addEventListener('pointerup',up);root.addEventListener('pointercancel',cleanup);root.addEventListener('click',click,true);root.addEventListener('keydown',key);window.addEventListener('blur',cleanup);
  root._dragCleanup=()=>{cleanup();root.removeEventListener('contextmenu',context);root.removeEventListener('pointerdown',down);root.removeEventListener('pointermove',move);root.removeEventListener('pointerup',up);root.removeEventListener('pointercancel',cleanup);root.removeEventListener('click',click,true);root.removeEventListener('keydown',key);window.removeEventListener('blur',cleanup)};
}
